insert into public.project_state_stage_requirements(project_state_id,stage,requirement_key,label,status,required,updated_by) select ps.id,'opportunity',v.requirement_key,v.label,'not_started'::public.readiness_state,true,ps.created_by from public.project_states ps cross join (values ('basic_identity','Basic project identity captured'),('initial_context','Initial context captured'),('next_step','Next step identified')) v(requirement_key,label) on conflict(project_state_id,stage,requirement_key) do nothing;
